query GetAllWorkspaces {
  workspaces {
    __typename
    workspaceId
    name
    displayName
    config
    workspaceRootPath
    absolutePath
    kind
    isTemp
  }
}

query ListCollaborationRootHistory {
  listCollaborationRootHistory {
